interface Beverage {
  cost(): number;
  describe(): string;
}

class DarkRoast implements Beverage {
  cost() { return 2.0; }
  describe() { return "Dark Roast"; }
}

abstract class ToppingDecorator implements Beverage {
  constructor(protected wrapped: Beverage) {}
  abstract cost(): number;
  abstract describe(): string;
}

class MilkDecorator extends ToppingDecorator {
  cost() { return this.wrapped.cost() + 0.5; }
  describe() { return `${this.wrapped.describe()} + Milk`; }
}
class SugarDecorator extends ToppingDecorator {
  cost() { return this.wrapped.cost() + 0.25; }
  describe() { return `${this.wrapped.describe()} + Sugar`; }
}

// Stack any combination at order time
const order = new SugarDecorator(new MilkDecorator(new DarkRoast()));
order.cost(); // 2.75
